package com.wipro.hibernate;import org.hibernate.*;import java.util.*;public class Main{public static void main(String[]a){try(Session s=HibernateUtil.getSessionFactory().openSession()){List<CarDetail>l=s.createQuery("from CarDetail",CarDetail.class).list();l.forEach(c->System.out.println(c.getRegNo()+" "+c.getModel()+" "+c.getColor()+" "+c.getManufacturer()));}HibernateUtil.getSessionFactory().close();}}